def classify_ml_problem(description: str) -> str:
    desc_lower = description.lower()
    if 'label' in desc_lower:
        return 'supervised'
    elif 'cluster' in desc_lower or 'segments' in desc_lower:
        return 'unsupervised'
    else:
        return 'unknown'

